import{_ as a,o as t,c as n,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"A Survey on Vision-Language-Action Models: An Action Tokenization Perspective","description":"","frontmatter":{"title":"A Survey on Vision-Language-Action Models: An Action Tokenization Perspective","arxiv":"2507.01925","date":"2025-07-02","authors":"Yifan Zhong, Fengshuo Bai, Shaofei Cai, Xuchuan Huang, Zhang Chen, Xiaowei Zhang, Yuanfei Wang, Shaoyang Guo, Tianrui Guan, et al.","categories":"cs.RO","topics":"VLA 综述, 动作 token 分类学, 具身基础模型","outline":[2,2]},"headers":[],"relativePath":"papers/2507.01925.md","filePath":"papers/2507.01925.md","lastUpdated":null}'),o={name:"papers/2507.01925.md"};function p(l,s,i,r,u,g){return t(),n("div",null,[...s[0]||(s[0]=[e('<h1 id="a-survey-on-vision-language-action-models-an-action-tokenization-perspective" tabindex="-1">A Survey on Vision-Language-Action Models: An Action Tokenization Perspective <a class="header-anchor" href="#a-survey-on-vision-language-action-models-an-action-tokenization-perspective" aria-label="Permalink to &quot;A Survey on Vision-Language-Action Models: An Action Tokenization Perspective&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2507.01925" target="_blank" rel="noreferrer">2507.01925</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-07-02</td></tr><tr><td><strong>作者</strong></td><td>Yifan Zhong, Fengshuo Bai, Shaofei Cai, Xuchuan Huang, Zhang Chen, Xiaowei Zhang, Yuanfei Wang, Shaoyang Guo, Tianrui Guan, et al.（共 14 位，通讯 Yuanpei Chen / Yaodong Yang）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>把所有 VLA 统一成&quot;一串 VLA 模块逐步生成 action token、信息逐级变得更可执行&quot;的链式框架，并按 token 形态划出语言描述/代码/affordance/轨迹/目标状态/隐表征/原始动作/推理八类，逐类给出优劣、经验成果与趋势判断。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">论文性质</p><p>这是一篇 70 页的综述（arXiv v1，5 张图、10 张汇编表），没有原创实验，也没有形式化数学。全文的贡献是一个统一框架 + 一套分类学 + 逐类的文献梳理与趋势判断。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLA 这个领域在两年内长出了形态极不一致的一堆系统：有的让 LLM 写 Python 调 API（Code as Policies），有的让 VLM 吐关键点（ReKep），有的生成一段未来视频再抽动作（UniPi），有的直接把 7 维动作离散成 token 接进语言模型（RT-2、OpenVLA），有的用流匹配头连续输出（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）。这些工作互相之间几乎无法比较：基准不同、本体不同、数据不同，连&quot;输入输出接口&quot;都不同。结果是新入场的人很难判断某个设计到底新在哪里，也很难判断某条路线的天花板在哪。</p><p>本文要解决的正是这个&quot;缺少共同坐标系&quot;的问题。作者的观察是：抛开表面差异，几乎所有 VLA 都可以写成同一件事——视觉与语言输入被一串模块反复处理，每个模块吐出一段&quot;逐渐更接地、更可执行&quot;的中间产物，直到最后一段可以直接送给控制器。他们把这些中间产物统一叫作 <strong>action token</strong>，并明确类比 LLM 里的 language token。有了这个坐标系，&quot;VLA 的主要设计选择是什么&quot;就有了一个具体答案：<strong>action token 的形态</strong>。这件事的价值不在于任何一个新数字，而在于它把一个靠直觉分类的领域变成了一个可以逐维度对照的领域。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>已有的 VLA / 具身智能综述通常按两条轴组织：一条是<strong>应用域</strong>（操作、导航、驾驶），一条是<strong>模块功能</strong>（感知、规划、控制）。前者的问题是把技术上同构的工作切开——RT-Trajectory（操作）与 DriveVLM（驾驶）都在生成轨迹当中间量，却被分到互不相干的章节。后者的问题是端到端模型无法被安置：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 里没有一个可以被叫作&quot;规划器&quot;的部件。</p><p>还有一类按训练范式分（模仿学习 / 强化学习 / 分层），这在动作表示已经统一的领域是合理的，但 VLA 恰恰是动作表示还没有收敛的阶段——同样是模仿学习，输出关键点和输出关节角是完全不同的两件事。</p><p>本文的定位就是补上这条缺失的轴。它没有否定已有综述的价值，而是指出：在动作表示尚未收敛之前，<strong>表示本身</strong>才是最有区分度的分类维度。这个判断本身是可以争论的（见 §11），但它至少是一个可证伪的立场。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>不使用本文自身的结论，重建路径大致如下。第一步来自一个已有的经验事实：LLM 的成功很大程度上是&quot;把一切转成 token 然后做 next-token 预测&quot;这个统一接口带来的。第二步是观察 VLA 的现状——它已经在大量借用 LLM/VLM 的骨干，但动作侧的接口五花八门。于是自然会问：VLA 里有没有一个东西扮演了 language token 的角色？</p><p>第三步是关键的一跳：如果把&quot;关键点&quot;&quot;目标图像&quot;&quot;子任务描述&quot;这些看似异质的中间产物都视为 token，那它们的共同点是什么？答案是<strong>它们都是某个模块的输出、都携带动作相关信息、都会被下一个模块消费</strong>。这个抽象层次一旦定下来，就能观察到一个规律：这些 token 沿链条排列时，信息是单调地&quot;变得更接地、更可执行&quot;的——从&quot;把茶泡好&quot;到&quot;拿起水壶&quot;到&quot;壶柄上的抓取点&quot;到关节角。第四步是把这条链上的 token 按形态归类，八类就是这样归出来的。第五步是给每一类找出它成立的理由（哪个基础模型支持它）与失效的理由（表达力/延迟/数据），这直接产出了 Table 1。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>VLA 里真正被设计的东西不是网络结构，而是<strong>中间产物的形态</strong>。你选择让模型吐一句话、一段代码、一个像素坐标、一段轨迹、一张未来图，还是 7 个浮点数，就同时决定了三件事：哪个基础模型能帮你生成它、需要什么标注才能训它、以及它能表达多细的动作。这就是为什么 action token 是 VLA 的核心设计变量——它是&quot;基础模型能力&quot;与&quot;物理可执行性&quot;之间的那个接口，而不同 token 类型只是在这条接口上取了不同的折中点。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>用文中给的例子&quot;泡茶&quot;走一遍这个框架如何应用。</p><ul><li><strong>识别 VLA 模块</strong>：作者的定义是&quot;最大的可微子网络&quot;与&quot;不可微的功能单元&quot;。以 VoxPoser 为例，LLM 是一个模块，VLM 是一个模块，运动规划算法也是一个模块（不可微，但仍算）。以 Hi Robot 为例，微调过的 PaliGemma 是一个模块，仿 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 训练的低层 VLA 是另一个模块。</li><li><strong>识别 action token</strong>：模块之间传递的东西就是 token。VoxPoser 链条是&quot;语言计划 → affordance map → 原始动作&quot;；Hi Robot 链条是&quot;语言计划 → 原始动作&quot;。此外，模块<strong>内部</strong>语义上有意义的中间生成也算 token，这条扩展让端到端模型也能被纳入框架。</li><li><strong>按形态归类</strong>：八类的定义分别是——语言描述（从高层 language plan 到低层 language motion）、代码（可执行片段或伪代码）、affordance（关键点 / 包围盒 / 分割掩码 / 稠密 affordance map 四个子类）、轨迹（末端、物体或场景的时序空间状态序列）、目标状态（预测的未来图像 / 点云 / 视频片段）、隐表征（在大规模数据上专门预训练的动作相关潜向量序列）、原始动作（可直接执行的低层控制指令）、推理（显式描述决策过程的自然语言，作为<strong>元 token</strong> 增强其他任何 token 的生成）。</li><li><strong>逐类填表</strong>：每一章都有一张汇编表，除了常规的方法/年份/基准外，还有两列很有信息量的自定义维度——<strong>previous module</strong> 与 <strong>next module</strong>，即&quot;这个 token 由什么生成、被什么消费&quot;。这两列实际上把每篇工作在链条上的位置显式化了，是本文最实用的组织手段。</li><li><strong>汇总判断</strong>：Table 1 给出每类的优势、局限与&quot;值得一提的经验成果&quot;（例如 language plan 对应 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 铺床、Hi Robot 做三明治；affordance-keypoint 对应 ReKep 倒茶；轨迹对应 RT-Trajectory 擦桌；目标状态对应 VPP 用移液管转移液体；隐表征对应 GO-1 叠短裤与 OmniJARVIS 在 Minecraft 挖钻石；原始动作对应 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 叠衣服）。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。全文没有出现过一个编号公式，所有判断以文字与汇编表形式给出。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>综述没有原创实验，能被当作&quot;证据&quot;的是三样东西，逐一评估其强度。</p><p><strong>汇编表（Tables 2–9）。</strong> 每类 token 一张，字段包含 previous/next module、数据来源、基准。这是全文最扎实的部分，因为它把&quot;某个 token 由谁生成、被谁消费&quot;这一维度显式列了出来，读者可以据此判断两篇工作是否真的同构。缺点是表里不含可比的性能数字——这是诚实的选择（跨基准数字本来就不可比），但也意味着分类学的<strong>判别力从未被定量检验</strong>。</p><p><strong>Table 1 的&quot;值得一提的经验成果&quot;列。</strong> 作者用的是&quot;做成了什么任务&quot;而非&quot;拿了多少分&quot;，例如 language plan 对应&quot;铺床&quot;&quot;做三明治&quot;。这是一种规避跨论文数字不可比的做法，代价是这一列几乎不可证伪：任务难度没有共同刻度，&quot;铺床&quot;与&quot;倒茶&quot;孰难无法判定。</p><p><strong>趋势判断（§13）。</strong> 作者给出的核心结论是：未来不属于任何单一 token，而属于分层组合——顶层用 language plan 与 code 做长时程规划与逻辑控制，中层用 3D affordance + 轨迹建模 + 目标视频预测组成中间运动表示，底层用策略模块映射到原始动作；推理作为元 token 贯穿各层。同时明确把<strong>隐表征排除</strong>在推荐架构之外，理由是粒度、语义完备性与任务对齐三方面的训练难题尚未解决，而显式 token 更易训练、可检视、可控。这是全文最有立场的一段，也是最容易被后续工作证伪或证实的一段。</p><p>另外几条判断值得单独记下：语言 motion 因表达力不足不太可能成为主流，但 language plan 在任务分解上不可替代；代码的潜力取决于能否建成融合感知与动作原语的完整函数库；affordance（做什么）与轨迹（怎么做）之间正在形成互补，并可由世界模型预测的目标状态共同支撑；原始动作是端到端的理想形态但被数据量卡住——作者给了一个很具体的量级估计：<strong>OXE 数据集的 token 总量约为大规模语言语料的 1/200,000</strong>。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：这篇综述提出把所有 VLA 视为&quot;一串模块产生一串 action token，信息逐级更可执行&quot;的统一链条，并按 token 形态分为八类。核心论点是 VLA 之间的主要设计差异就在于 token 形态，因为它同时决定了哪个基础模型可用、需要什么标注、以及能表达多细的动作。作者逐类给出优劣（例如轨迹可从域外人类视频训练但 3D 表达力差；目标状态数据可扩展性强但生成质量与延迟是瓶颈；原始动作最少人工先验但被数据稀缺卡死），并判断未来是分层组合而非单一赢家。他们把隐表征排除在推荐架构外，理由是粒度与任务对齐的训练难题。全篇没有实验、没有公式，价值在于坐标系而非结论。</p><p><strong>三句话版</strong>：VLA 的核心设计变量是中间表示的形态，不是网络结构。八类 token 各有明确的能力边界，未来大概率是顶层语言/代码、中层 affordance+轨迹+目标状态、底层原始动作的分层组合。全文最硬的一个数字是&quot;机器人数据比语言语料少约五个数量级&quot;，它解释了为什么端到端路线短期内走不通。</p><p><strong>一句话版</strong>：把 VLA 当成 &quot;action token 的自回归链&quot;来看，整个领域的设计空间就塌成了一个可比较的坐标轴。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是框架层面的：<strong>&quot;VLA 模块与 action token 交替排列成一条链&quot;这个抽象具有判别力</strong>。如果它不成立，那么八分类就不是对设计空间的划分，而只是对术语的重新命名，全文的组织价值随之坍塌。</p><p>它很可能不成立，有三条理由。第一，作者自己在 §13.2 明确写道，未来的 VLA agent&quot;不应被线性架构所限制&quot;，模块与 token 应当被自适应地调用与管理，形成双向、图结构的拓扑。也就是说，作者一边用链式抽象组织全文，一边预告这个抽象即将过期。第二，token 的定义被显式放宽到&quot;模块<strong>内部</strong>语义上有意义的中间生成也算 action token&quot;。这条扩展是为了容纳端到端模型，但它使定义几乎不可证伪——一个端到端网络的任何一层激活都可以被事后声称&quot;语义上有意义&quot;。第三，八类的容量极不均衡：<strong>原始动作</strong>这一类实际上吞掉了 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、RDT、GR00T N1、OpenVLA 等近两年绝大多数受关注的工作，而这些工作彼此的差异（动作头形态、预训练数据、跨本体对齐方式）远大于它们与&quot;轨迹类&quot;工作的差异。当一个分类轴上的某一格装下了半个领域时，这个轴的分辨率就已经不够用了。</p><p>论文为该假设提供的证据是 Figure 1 的两个案例（Hi Robot 与 VoxPoser）加上后续章节的文献覆盖度。这属于&quot;存在性证明&quot;——能找到很多例子被框架容纳，但从未检验框架<strong>排除</strong>了什么。缺的是一个反向测试：找出无法被自然地写成链式 token 序列的 VLA（例如带在线重规划的闭环系统、或动作与感知交织的隐式模型），并说明框架如何处理它们。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>综述无法&quot;复现&quot;，但它的核心 claim（token 形态是主要设计变量）是可以在一周内做一次最小检验的。</p><ul><li><strong>设定</strong>：固定 LIBERO（四个套件）与一个固定的 VLM 骨干（例如 Qwen2.5-VL-3B）、固定演示数据与训练预算（相同 GPU 小时、相同步数）。</li><li><strong>实现三种 token 形态</strong>，其余全部相同：(a) 原始动作 chunk（离散化后 next-token 预测）；(b) 轨迹 token（预测末端在图像平面上的 2D 路径，再由一个固定的控制器跟随）；(c) 目标状态 token（预测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 步后的目标图像，再由一个固定的逆动力学模型出动作）。</li><li><strong>测量</strong>：四个套件的成功率、每步延迟、以及<strong>在演示数量减半时的成功率降幅</strong>（数据效率）。</li><li><strong>判据</strong>：若三者的排序在四个套件上一致，且差距明显大于随机种子波动，则&quot;token 形态是主要设计变量&quot;在这一受控设定下成立；若排序随套件翻转、或差距落在种子噪声内，则说明在同骨干同数据条件下 token 形态并非主导因素，主导因素更可能是数据与本体匹配。这个实验的价值在于，它是把一个分类学主张转成实验主张的最小代价方案，而目前整个领域都没有做过。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是提出一条<strong>竞争的分类轴</strong>并论证它的预测力更强：<strong>监督信号的来源与规模</strong>（该 token 的训练标注从哪来、能扩到多大），而非 token 的形态。</p><p>论证如下。在&quot;原始动作&quot;这一格内部，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 OpenVLA 的性能差距，主要由预训练数据量、本体覆盖与动作头形态决定，与&quot;它们都用原始动作&quot;这一共同点无关。跨格来看，VoxPoser（affordance）与 Code as Policies（代码）的真正差异是前者链条末端接了一个运动规划器、后者接了一组人工 API——即&quot;下游消费者&quot;决定了系统能力，而不是&quot;token 长什么样&quot;。作者自己设计的 previous/next module 两列恰恰指向这一点，却没有把它提升为分类轴。</p><p>更强的是本文自身的证据结构：Table 1 的局限列里，<strong>&quot;数据稀缺&quot;&quot;标注成本&quot;&quot;延迟&quot;这三条反复出现在不同 token 类型下</strong>——语言描述是延迟高、代码是依赖预定义 API、轨迹是缺 VLM 支持与语义、目标状态是生成质量与延迟、原始动作是数据稀缺。这说明约束更多来自监督与算力，而非表示形态本身。</p><p>可执行的反例实验：取 30 篇有公开数字的 VLA 工作，为每篇标注 (i) token 类型、(ii) 训练数据量级、(iii) 评测本体是否与训练本体同形、(iv) 是否使用了不可微的外部模块（规划器、抓取器、分割器）。用这四个变量分别拟合&quot;相对同期基线的提升幅度&quot;，比较各自的解释力。如果 (ii)+(iii) 的解释力显著高于 (i)，那么 token 分类学就是一个描述性而非预测性的框架——这不否定它的组织价值，但会推翻&quot;token 形态是<strong>主要</strong>设计选择&quot;这一核心断言。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>一个非增量的方向：<strong>把 action token 从分类学对象变成率失真意义下的可测量对象</strong>。</p><p>(a) 驱动它的局限：本文最大的遗憾是八类之间无法定量比较——Table 1 只能用&quot;做成了什么任务&quot;当经验成果，因为跨基准数字不可比。只要缺少一个共同刻度，&quot;哪类 token 更好&quot;就永远只能靠立场表态。而作者自己在类比 language token 时其实已经暗示了刻度的存在：语言 tokenizer 是可以按压缩率评价的。</p><p>(b) 可借鉴的相邻领域工具：信息论里的<strong>率失真理论</strong>与神经压缩里的<strong>任务导向编码</strong>。把每一类 action token 视为在观测-动作通道上的一个有损编码：码率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> = 该 token 每决策步携带的比特数（语言 plan 是几十比特、关键点是几十比特、目标图像是几千比特、原始动作 chunk 是几百比特），失真 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span></span></span></span> = 用一个<strong>固定的</strong>下游控制器消费该 token 时的闭环任务代价。这样八类 token 就落在同一张 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span>–<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span></span></span></span> 平面上，&quot;分层组合&quot;的主张变成一个可验证的命题：不同层是否确实落在这条曲线的不同区段。</p><p>(c) 第一个实验长什么样：选一个有真值动作的多任务数据集（LIBERO 或 DROID 的子集），把同一批演示分别编码成五种 token（language motion、关键点、末端 2D 轨迹、目标图像、动作 chunk），用同一个小型解码控制器把每种 token 映射回动作，测量&quot;每步比特数 vs 动作重建误差 vs 闭环成功率&quot;三元组。第一步可以完全离线（只测重建误差），成本极低。如果不同 token 类型的点确实构成一条清晰的凸包络，那么就有了一个真正的坐标；如果它们散成一团，说明 token 形态与信息量并不对应，本文的分类轴就需要被更细的维度替代。这个方向的好处是：无论结论如何，它都把&quot;该用哪种中间表示&quot;从口味之争变成了可测量的工程选择。</p>',48)])])}const m=a(o,[["render",p]]);export{h as __pageData,m as default};
